import { Box } from "@chakra-ui/layout";
import SingleChat from "./SingleChat";
import { ChatState } from "../Context/ChatProvider";

const Chatbox = ({ fetchAgain, setFetchAgain }) => {
  const { selectedChat, user } = ChatState();

  // 🎥 Create Meeting + Send Link
  const createMeeting = async () => {
    if (!selectedChat) return;

    const roomID = selectedChat._id;
    const url = `https://meet.jit.si/${roomID}`;

    // 👉 Open meeting for current user
    window.open(url, "_blank");

    try {
      // 👉 Send meeting link as message to chat
      await fetch("/api/message", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${user.token}`, // IMPORTANT
        },
        body: JSON.stringify({
          content: `📢 Meeting started! Join here 👉 ${url}`,
          chatId: selectedChat._id,
        }),
      });

      // 👉 Refresh messages
      setFetchAgain(!fetchAgain);
    } catch (error) {
      console.log("Error sending meeting link", error);
    }
  };

  return (
    <Box
      d={{ base: selectedChat ? "flex" : "none", md: "flex" }}
      alignItems="center"
      flexDir="column"
      p={3}
      bg="white"
      w={{ base: "100%", md: "68%" }}
      borderRadius="lg"
      borderWidth="1px"
      position="relative"
    >
      {/* 🎥 Meet Button */}
      {selectedChat && (
        <button
          onClick={createMeeting}
          style={{
            position: "absolute",
            top: "10px",
            right: "15px",
            background: "linear-gradient(135deg, #3a86ff, #4361ee)",
            color: "white",
            border: "none",
            padding: "7px 14px",
            borderRadius: "10px",
            cursor: "pointer",
            fontSize: "14px",
            fontWeight: "500",
            zIndex: 10,
            boxShadow: "0px 4px 12px rgba(0,0,0,0.2)",
          }}
        >
          🎥 Meet
        </button>
      )}

      {/* Existing Chat Component */}
      <SingleChat fetchAgain={fetchAgain} setFetchAgain={setFetchAgain} />
    </Box>
  );
};

export default Chatbox;
